
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='banxu.classroom.v1';
const blank=()=>({version:1,className:'我的班级',students:[],exams:[],seats:{},rows:7,extraRow:5,showScores:false,examId:'',subject:'总分',discipline:{},callRange:'single',callSubject:''});
let state=blank(), history=[], selected=null, page='seat', importBook=null, importKind='roster', staged=null, toastTimer, saveFailed=false;
const ROWS_MIN=6,ROWS_MAX=7;
const seatIdsFor=rows=>Array.from({length:rows},(_,r)=>Array.from({length:8},(_,c)=>`R${r+1}C${c+1}`)).flat().concat(['X1','X2']);
const capacityFor=rows=>rows*8+2;
const fillOrderFor=(rows,extraRow)=>{const out=[];for(let r=1;r<=rows;r++){for(let c=1;c<=8;c++)out.push(`R${r}C${c}`);if(r===extraRow)out.push('X1');if(r===extraRow+1)out.push('X2');}return out;};
const seatIds=seatIdsFor(ROWS_MAX);
const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
function validState(s){if(!s||s.version!==1||!Array.isArray(s.students)||!Array.isArray(s.exams)||!s.seats||typeof s.seats!=='object'||Array.isArray(s.seats))return false;let ids=new Set();for(const p of s.students){if(!p||typeof p.id!=='string'||!p.id.trim()||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>100)return false;ids.add(p.id);if(p.gender!=null&&typeof p.gender!=='string'||p.note!=null&&typeof p.note!=='string')return false;}const seated=new Set();for(const [k,id] of Object.entries(s.seats)){if(!seatIds.includes(k)||!ids.has(id)||seated.has(id))return false;seated.add(id);}const exams=new Set();for(const e of s.exams){if(!e||typeof e.id!=='string'||exams.has(e.id)||typeof e.name!=='string'||!Array.isArray(e.subjects)||!e.subjects.length||e.subjects.some(x=>typeof x!=='string')||new Set(e.subjects).size!==e.subjects.length||!e.scores||typeof e.scores!=='object')return false;exams.add(e.id);for(const [id,v] of Object.entries(e.scores)){if(!ids.has(id)||!v||typeof v!=='object')return false;for(const [subject,n] of Object.entries(v)){if(!e.subjects.includes(subject)||(n!==null&&(typeof n!=='number'||!Number.isFinite(n)||n<0)))return false;}}}return typeof s.className==='string'&&s.className.length<=100&&(s.rows===undefined||(Number.isInteger(s.rows)&&s.rows>=ROWS_MIN&&s.rows<=ROWS_MAX))&&Number.isInteger(s.extraRow)&&s.extraRow>=1&&s.extraRow<=(s.rows||ROWS_MAX)-1&&typeof s.showScores==='boolean'&&typeof s.examId==='string'&&typeof s.subject==='string';}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!validState(parsed))throw Error('invalid');state=parsed;normalizeExamDates(state);normalizeSeatRows(state);}}catch(e){saveFailed=true;setTimeout(()=>toast('本地数据无法读取。请恢复备份；当前不会覆盖原数据。'),500);}
function save(){if(saveFailed){$('#saveState').textContent='本地存储不可用，请导出备份';return false;}try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveState').innerHTML='<i class="dot"></i>已保存到此浏览器';return true;}catch(e){$('#saveState').textContent='保存失败，请导出备份';toast('浏览器无法保存，请及时导出备份。');return false;}}
function checkpoint(){history.push(JSON.stringify(state));if(history.length>30)history.shift();}
function changed(message){save();render();if(message)toast(message);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4000);}
function getExam(){return state.exams.find(e=>e.id===state.examId);}function toISODate(v){const s=String(v??'').trim();if(!s)return '';let m=s.match(/^(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/);if(!m){const d=s.match(/^(\d{4})(\d{2})(\d{2})$/);if(d)m=[d[0],d[1],d[2],d[3]];}if(!m)return '';const y=+m[1],mo=+m[2],da=+m[3];if(mo<1||mo>12||da<1||da>31)return '';return `${y}-${String(mo).padStart(2,'0')}-${String(da).padStart(2,'0')}`;}function examDateLabel(e){return toISODate(e?.date)||'未设置时间';}function sortedExams(){return [...state.exams].sort((a,b)=>toISODate(b.date).localeCompare(toISODate(a.date)));}function normalizeExamDates(s){for(const e of s.exams||[]){const iso=toISODate(e.date);if(iso)e.date=iso;}}
function normalizeSeatRows(s){if(!Number.isInteger(s.rows)||s.rows<ROWS_MIN||s.rows>ROWS_MAX)s.rows=ROWS_MAX;let maxRow=0;for(const k of Object.keys(s.seats||{}))if(k.startsWith('R'))maxRow=Math.max(maxRow,Number(k[1])||0);if(maxRow>s.rows)s.rows=Math.min(ROWS_MAX,maxRow);if(!Number.isInteger(s.extraRow)||s.extraRow<1)s.extraRow=5;if(s.extraRow>s.rows-1)s.extraRow=Math.max(1,s.rows-1);}function examSubjects(ex){return (ex?.subjects||[]).filter(s=>ex?.scores&&Object.values(ex.scores).some(v=>typeof v?.[s]==='number'&&Number.isFinite(v[s])));}let examPreviewId='';let examPreviewSort={key:'id',dir:1};function sortPreview(list,exam){const {key,dir}=examPreviewSort;const value=p=>key==='id'?p.id:key==='name'?p.name:(exam.scores?.[p.id]?.[key]);const idOf=p=>String(p.id).localeCompare(String(p.id));return [...list].sort((a,b)=>{const va=value(a),vb=value(b);if(key==='id'||key==='name'){const r=key==='name'?String(va).localeCompare(String(vb),'zh-CN'):String(va).localeCompare(String(vb),'zh-CN',{numeric:true});return r*dir||idOf(a);}const na=typeof va==='number'&&Number.isFinite(va),nb=typeof vb==='number'&&Number.isFinite(vb);if(!na&&!nb)return String(a.id).localeCompare(String(b.id),'zh-CN',{numeric:true});if(!na)return 1;if(!nb)return -1;return (va-vb)*dir||String(a.id).localeCompare(String(b.id),'zh-CN',{numeric:true});});}const sortMark=key=>examPreviewSort.key===key?(examPreviewSort.dir>0?' ▲':' ▼'):'';
function mark(p){if(!state.showScores)return '';const v=getExam()?.scores[p.id]?.[state.subject];return v==null?'缺考 / 未录入':`${v} 分`;}
function studentSeat(id){return Object.keys(state.seats).find(k=>state.seats[k]===id);}
function seatLabel(k){if(k==='X1'||k==='X2')return `中央 ${state.extraRow+(k==='X2'?1:0)} 排`;const m=k.match(/R(\d)C(\d)/);return `${m[1]} 排 ${9-Number(m[2])} 列`;}
function render(){
$('#className').value=state.className;$('#statStudents').innerHTML=`${state.students.length}<small>人</small>`;$('#statSeated').innerHTML=`${Object.keys(state.seats).length}<small>/ ${capacityFor(state.rows)}</small>`;
$('#legendRegular').textContent=`常规座位 ${state.rows*8}`;$('#legendCapacity').textContent=`4 组 × 2 列 × ${state.rows} 排 · 共 ${capacityFor(state.rows)} 座`;$('#statWaiting').innerHTML=`${state.students.length-Object.keys(state.seats).length}<small>人</small>`;$('#statExams').innerHTML=`${state.exams.length}<small>次</small>`;$('#intro').classList.toggle('hidden',state.students.length>0);$('#showScores').checked=state.showScores;$('#showScores').disabled=!state.exams.length;
if(!getExam())state.examId=sortedExams()[0]?.id||'';if(!state.discipline||typeof state.discipline!=='object')state.discipline={};if(!['single','recent3','recent5','all'].includes(state.callRange))state.callRange='single';$('#examSelect').innerHTML=state.exams.length?sortedExams().map(e=>`<option value="${esc(e.id)}">${esc(e.name)}${toISODate(e.date)?`（${esc(toISODate(e.date))}）`:''}</option>`).join(''):'<option>暂无考试</option>';$('#examSelect').value=state.examId;$('#examSelect').disabled=!state.exams.length;let subjects=examSubjects(getExam());if(!subjects.includes(state.subject))state.subject=subjects.includes('总分')?'总分':subjects[0]||'总分';$('#subjectSelect').innerHTML=subjects.length?subjects.map(s=>`<option>${esc(s)}</option>`).join(''):'<option>总分</option>';$('#subjectSelect').value=state.subject;$('#subjectSelect').disabled=!subjects.length;const rowCount=state.rows;$('#rowsSelect').value=rowCount;$('#extraRow').innerHTML=Array.from({length:rowCount-1},(_,i)=>`<option value="${i+1}">第 ${i+1}–${i+2} 排</option>`).join('');$('#extraRow').value=Math.min(state.extraRow,rowCount-1);$('#undoBtn').disabled=!history.length;$('#printTitle').textContent=state.className+' · 座位表'+(state.showScores&&getExam()?`（${getExam().name} · ${examDateLabel(getExam())} · ${state.subject}）`:'');
let html='';for(const [start,end,label] of [[2,4,'第四组'],[5,7,'第三组'],[7,8,'加座'],[8,10,'第二组'],[11,13,'第一组']])html+=`<div class="group-label" style="grid-column:${start}/${end};grid-row:1">${label}</div>`;
const cols=[2,3,5,6,8,9,11,12];for(let r=1;r<=state.rows;r++){html+=`<div class="row-label" style="grid-row:${r+1};grid-column:1">${String(r).padStart(2,'0')}</div>`;for(let c=1;c<=8;c++)html+=seatHTML(`R${r}C${c}`,r+1,cols[c-1],false);}html+=seatHTML('X1',state.extraRow+1,7,true)+seatHTML('X2',state.extraRow+2,7,true);$('#seating').innerHTML=html;$('#seating').classList.toggle('rows-7',state.rows===7);
renderWaiting();renderRoster();renderExams();renderCall();renderDisciplinePage();if(bubbleStudentId)renderBubbles();if(saveFailed)$('#saveState').textContent='本地存储不可用，请导出备份';
}
function seatHTML(k,row,col,central){const p=state.students.find(x=>x.id===state.seats[k]);const gender=String(p?.gender||'').trim().toLowerCase();const genderClass=['男','男生','男性','male','m'].includes(gender)?'gender-boy':['女','女生','女性','female','f'].includes(gender)?'gender-girl':'';return `<button class="seat ${p?'occupied':''} ${genderClass} ${central?'central':''} ${p&&selected===p.id?'selected':''}" data-seat="${k}" ${p?`data-student="${esc(p.id)}"`:''} style="grid-row:${row};grid-column:${col}" aria-label="${esc(seatLabel(k)+(p?' '+p.name+' '+mark(p):' 空座'))}" title="${esc(p?`${p.name} · ${seatLabel(k)}${state.showScores?' · '+state.subject+' '+mark(p):''}`:seatLabel(k))}"><span class="seat-code">${central?'中-'+(state.extraRow+(k==='X2'?1:0)):(9-Number(k[3]))+'-'+k[1]}</span>${p?`<span class="seat-name">${esc(p.name)}</span>${state.showScores?`<span class="seat-score">${esc(mark(p))}</span>`:''}`:'<span class="empty-plus">＋</span>'}</button>`;}
function renderWaiting(){const waiting=state.students.filter(p=>!studentSeat(p.id));$('#waitingCount').textContent=waiting.length;const q=$('#searchWaiting').value.trim().toLowerCase();const show=waiting.filter(p=>(p.name+p.id).toLowerCase().includes(q));$('#waitingList').innerHTML=show.length?show.map(p=>`<button class="student ${selected===p.id?'selected':''}" data-student="${esc(p.id)}" title="${esc(p.id)}"><span>${esc(p.name)}</span><small>${esc(state.showScores?mark(p):p.id)}</small></button>`).join(''):`<div class="empty-state">${q?'没有匹配的学生':state.students.length?'✓ 所有同学已安排入座':'还没有学生<br>点击右上角导入名单'}</div>`;}
function renderRoster(){const q=$('#rosterSearch').value.trim().toLowerCase(),list=state.students.filter(p=>(p.name+p.id).toLowerCase().includes(q));$('#rosterTable').innerHTML=list.length?`<table><thead><tr><th>学号</th><th>姓名</th><th>性别</th><th>当前座位</th><th>备注</th><th>操作</th></tr></thead><tbody>${list.map(p=>`<tr><td>${esc(p.id)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.gender||'—')}</td><td><span class="badge">${studentSeat(p.id)?seatLabel(studentSeat(p.id)):'待安排'}</span></td><td>${esc(p.note||'—')}</td><td><button class="small" data-edit="${esc(p.id)}">编辑</button> <button class="small danger" data-delete="${esc(p.id)}">删除</button></td></tr>`).join('')}</tbody></table>`:'<div class="table-empty">'+(q?'没有匹配的学生':'暂无学生名单<br>导入 Excel 文件，或手动添加学生。')+'</div>';}
function renameExam(id){const exam=state.exams.find(e=>e.id===id);if(!exam)return;openModal('修改考试信息',`<div class="form-row"><div class="field"><label for="renameExamInput">考试名称（必填）</label><input id="renameExamInput" required maxlength="80" value="${esc(exam.name)}" placeholder="例如：高一上学期第一次月考"></div><div class="field"><label for="renameExamDate">考试时间（必填）</label><input id="renameExamDate" type="date" required value="${esc(toISODate(exam.date))}"></div></div>`,`<button data-close>取消</button><button class="primary" id="saveExamName">保存信息</button>`);$('#renameExamInput').focus();$('#saveExamName').onclick=()=>{const name=$('#renameExamInput').value.trim(),date=$('#renameExamDate').value;if(!name){toast('请填写考试名称');$('#renameExamInput').focus();return;}if(!toISODate(date)){toast('请选择考试时间');$('#renameExamDate').focus();return;}checkpoint();exam.name=name;exam.date=toISODate(date);state.exams=sortedExams();$('#modal').close();changed('考试信息已更新');};}

function renderExams(){
 if(!examPreviewId||!state.exams.some(e=>e.id===examPreviewId))examPreviewId=sortedExams()[0]?.id||'';const selectedExam=state.exams.find(e=>e.id===examPreviewId);
 const orderedExams=sortedExams();
 $('#examCards').innerHTML=orderedExams.length?orderedExams.map(e=>{const active=e.id===examPreviewId,subs=examSubjects(e);return `<article class="panel exam-card ${active?'selected':''}"><div class="eyebrow">EXAM RECORD / 考试档案</div><h3>${esc(e.name)}</h3><p>${Object.keys(e.scores).length} 人有成绩记录 · 考试时间 ${esc(examDateLabel(e))}<br>已考科目：${esc(subs.join(' / ')||'暂无有效成绩')}${e.sourceFormat?`<br>来源：${esc(e.sourceFormat)}`:''}</p><div class="actions"><button class="small ${active?'primary':''}" data-preview-exam="${esc(e.id)}">${active?'正在预览':'在线预览'}</button><button class="small" data-view-exam="${esc(e.id)}">用于排座</button><button class="small" data-rename-exam="${esc(e.id)}">修改信息</button><button class="small" data-export-exam="${esc(e.id)}">导出</button><button class="small danger" data-delete-exam="${esc(e.id)}">删除</button></div></article>`}).join(''):'<div class="panel table-empty" style="grid-column:1/-1">还没有考试记录<br>导入成绩后，这里会显示在线预览表。</div>';
 if(!selectedExam){$('#examPreviewPanel').innerHTML='<div class="table-empty">导入考试后会在这里生成在线预览表。</div>';return;}
 const subs=examSubjects(selectedExam),q=($('#examPreviewSearch')?.value||'').trim().toLowerCase(),people=sortPreview(state.students.filter(p=>(p.name+p.id).toLowerCase().includes(q)),selectedExam);
 $('#examPreviewPanel').innerHTML=`<div class="exam-preview-head"><div><h2>${esc(selectedExam.name)}</h2><p>在线预览 · 考试时间 ${esc(examDateLabel(selectedExam))} · ${people.length} 位学生 · ${subs.length} 门已考科目 · 点表头排序</p></div><input id="examPreviewSearch" class="preview-filter" placeholder="搜索姓名或学号" value="${esc(q)}"></div><div class="exam-preview-table"><table><thead><tr><th><button class="sort-btn" data-sort="id" title="按学号排序">学号${sortMark('id')}</button></th><th><button class="sort-btn" data-sort="name" title="按姓名排序">姓名${sortMark('name')}</button></th>${subs.map(s=>`<th><button class="sort-btn" data-sort="${esc(s)}" title="按${esc(s)}成绩排序">${esc(s)}${sortMark(s)}</button><br><span class="rank-cell">成绩 / 校次 / 班次</span></th>`).join('')}</tr></thead><tbody>${people.map(p=>{const vals=selectedExam.scores[p.id]||{},ranks=selectedExam.ranks?.[p.id]||{};return `<tr><td>${esc(p.id)}</td><td><b>${esc(p.name)}</b></td>${subs.map(s=>{const rank=ranks[s]||{};return `<td>${vals[s]??'—'}<br><span class="rank-cell">${rank.school??'—'} / ${rank.class??'—'}</span></td>`}).join('')}</tr>`}).join('')}</tbody></table>${people.length?'':'<div class="table-empty">没有匹配的学生</div>'}</div>`;
 $('#examPreviewSearch').oninput=renderExams; $$('#examPreviewPanel .sort-btn').forEach(b=>b.onclick=()=>{const key=b.dataset.sort;examPreviewSort=(examPreviewSort.key===key)?{key,dir:-examPreviewSort.dir}:{key,dir:key==='id'||key==='name'?1:-1};renderExams();});
}
function setPage(p){page=p;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));for(const name of ['seat','roster','exams','discipline','call'])$('#'+name+'View').classList.toggle('hidden',name!==p);const titles={discipline:['DISCIPLINE / 违纪情况','每位同学的违纪记录，一目了然','只列出有违纪记录的学生，点进去可查看明细、补充或删除。'],call:['ROLL CALL / 随机点名','让每位同学，都有参与的机会','按考试成绩分类抽取，支持一轮内不重复点名。'],seat:['CLASSROOM / 座位安排','为每一位同学，找到合适的位置','拖动安排座位，结合成绩，让班级布局一目了然。'],roster:['STUDENTS / 学生名单','每一位同学，都在这里','用学号关联名单与考试成绩，支持同名学生。'],exams:['EXAMS / 考试成绩','记录成长，让安排有据可依','保留多次考试记录，自由切换总分与单科成绩。']};$('#pageEyebrow').textContent=titles[p][0];$('#pageTitle').textContent=titles[p][1];$('#pageSubtitle').textContent=titles[p][2];$('#importBtn').textContent=p==='exams'?'＋ 导入考试成绩':'＋ 导入学生名单';}
function moveStudent(id,target){if(!state.students.some(p=>p.id===id))return;const from=studentSeat(id);if(from===target)return;checkpoint();if(target){const displaced=state.seats[target];state.seats[target]=id;if(from){if(displaced)state.seats[from]=displaced;else delete state.seats[from];}}else if(from)delete state.seats[from];selected=null;changed(target?'座位已更新':'已移回待安排区');}
let drag=null,suppressClick=false;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-student]');if(!el||e.button!==0||$('#modal').open)return;drag={id:el.dataset.student,x:e.clientX,y:e.clientY,active:false,ghost:null};});
document.addEventListener('pointermove',e=>{if(!drag)return;if(!drag.active&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6){drag.active=true;drag.ghost=document.createElement('div');drag.ghost.className='drag-ghost';drag.ghost.textContent=state.students.find(p=>p.id===drag.id).name;document.body.append(drag.ghost);}if(drag.active){e.preventDefault();drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';$$('.over').forEach(el=>el.classList.remove('over'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-seat],#waitingDrop');target?.classList.add('over');}},{passive:false});
function clearDrag(){drag?.ghost?.remove();$$('.over').forEach(el=>el.classList.remove('over'));drag=null;}
document.addEventListener('pointerup',e=>{if(!drag)return;if(drag.active){suppressClick=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-seat],#waitingDrop');const id=drag.id;clearDrag();if(target)moveStudent(id,target.dataset.seat||null);setTimeout(()=>suppressClick=false,100);}else clearDrag();});
