const DISC_TYPES=['晚自习违纪','晚自习静校期间违纪','早自习违纪','迟到违纪','眼保健操违纪','午休违纪','寝室违纪','带水杯进教室'];
const DISC_ALIASES={'晚自习静校期间违纪':['晚自习静校期间违纪','晚自习静校期间','晚自习静校','静校期间违纪','静校违纪','静校'],'晚自习违纪':['晚自习违纪','晚自习','晚修违纪','晚修'],'早自习违纪':['早自习违纪','早自习','早读违纪','早读'],'迟到违纪':['迟到违纪','迟到'],'眼保健操违纪':['眼保健操违纪','眼保健操','眼操违纪','眼操'],'午休违纪':['午休违纪','午休'],'寝室违纪':['寝室违纪','寝室','宿舍违纪','宿舍'],'带水杯进教室':['带水杯进教室','带水杯','水杯']};
