function parseDiscText(text,defaultDate){
 const aliases=[];for(const [t,list] of Object.entries(DISC_ALIASES))for(const a of list)aliases.push([a,t]);
 aliases.sort((a,b)=>b[0].length-a[0].length);
 const students=[...state.students].sort((a,b)=>b.name.length-a.name.length);
 const rows=[];
 for(const raw of String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)){
  let line=raw,date='',note='';
  const full=line.match(/(20\d{2})[-/.年](\d{1,2})[-/.月](\d{1,2})/);
  if(full){date=toISODate(full[0]);line=line.replace(full[0],' ');}
  else{
   const short=line.match(/(\d{1,2})[-/.月](\d{1,2})[日号]?/);
   if(short){const iso=toISODate(`${new Date().getFullYear()}-${short[1]}-${short[2]}`);if(iso){date=iso;line=line.replace(short[0],' ');}}
  }
  if(!date){if(defaultDate)date=toISODate(defaultDate)||'';if(date)note='按默认日期';}
  let type='';
  for(const [a,t] of aliases){if(line.includes(a)){type=t;line=line.replace(a,' ');break;}}
  const found=[];
  for(const p of students){if(p.name&&line.includes(p.name)){if(!found.some(f=>f.id===p.id))found.push(p);line=line.split(p.name).join(' ');}}
  const reason=line.replace(/[、,，。;；:：\s]+/g,' ').trim().slice(0,200);
  if(!found.length){rows.push({raw,date,type,reason,status:'未找到学生',ok:false});continue;}
  if(!type){rows.push({raw,date,name:found.map(p=>p.name).join('、'),students:found,reason,status:'缺少违纪类型',ok:false});continue;}
  if(!date){rows.push({raw,date,name:found.map(p=>p.name).join('、'),students:found,type,reason,status:'缺少日期',ok:false});continue;}
  for(const p of found)rows.push({raw,date,type,reason,student:p,status:note||'可导入',ok:true});
 }
 return rows;
}
function openDiscImport(){
 openModal('快速导入违纪记录',
  `<p>把备忘录里的文字直接粘贴进来，每行一条。可写成“9月20日 张三 晚自习违纪”“2026-10-11 李四、王五 迟到”“张三 眼操”。姓名按班级名单匹配，类型支持晚自习／静校／早自习／迟到／眼操／午休／寝室／水杯等简称；缺日期时用下面的默认日期。</p>`
  +`<div class="form-row"><div class="field"><label for="discDefaultDate">缺省日期</label><input id="discDefaultDate" type="date" value="${new Date().toISOString().slice(0,10)}"></div></div>`
  +`<div class="field"><label for="discText">粘贴文字（每行一条）</label><textarea id="discText" style="min-height:150px;width:100%" placeholder="9月20日 张三 晚自习违纪&#10;9月21日 李四、王五 迟到"></textarea></div>`
  +`<div id="discParseNotice" class="notice" style="display:none"></div><div id="discParsePreview" class="preview"></div>`,
  `<button data-close>取消</button><button class="primary" id="discImportCommit" disabled>导入</button>`);
 $('#discText').oninput=previewDiscImport;
 $('#discDefaultDate').onchange=previewDiscImport;
 previewDiscImport();
}
function previewDiscImport(){
 const rows=parseDiscText($('#discText')?.value||'',$('#discDefaultDate')?.value||'');
 discStaged=rows;const ok=rows.filter(r=>r.ok);
 $('#discImportCommit').disabled=!ok.length;
 const notice=$('#discParseNotice');
 notice.style.display=rows.length?'block':'none';
 notice.className='notice'+(ok.length===rows.length?'':' error');
 notice.textContent=rows.length?`共 ${rows.length} 行，可导入 ${ok.length} 条${rows.length-ok.length?`，${rows.length-ok.length} 行需要修改（不会导入）`:''}`:'';
 $('#discParsePreview').innerHTML=rows.length?'<table><thead><tr><th>日期</th><th>学生</th><th>类型</th><th>备注</th><th>状态</th></tr></thead><tbody>'+rows.slice(0,100).map(r=>`<tr><td>${esc(r.date||'—')}</td><td>${esc(r.student?r.student.name:(r.name||r.raw.slice(0,24)))}</td><td>${esc(r.type||'—')}</td><td>${esc(r.reason||'—')}</td><td>${esc(r.status)}</td></tr>`).join('')+'</tbody></table>':'';
 $('#discImportCommit').onclick=commitDiscImport;
}
function commitDiscImport(){
 const rows=(discStaged||[]).filter(r=>r.ok);if(!rows.length)return;
 if(!state.discipline)state.discipline={};
 checkpoint();let added=0,dup=0;
 for(const r of rows){
  const list=state.discipline[r.student.id]||(state.discipline[r.student.id]=[]);
  const same=list.some(x=>toISODate(x.date)===toISODate(r.date)&&(x.type||'')===r.type&&(x.reason||'')===(r.reason||''));
  if(same){dup++;continue;}
  list.push({date:r.date,type:r.type,reason:r.reason||''});added++;
 }
 $('#modal').close();
 changed(`已导入 ${added} 条违纪记录${dup?`，跳过重复 ${dup} 条`:''}`);
}
