function previewImport(){try{const rows=XLSX.utils.sheet_to_json(importBook.Sheets[$('#sheetSelect').value],{header:1,defval:'',raw:false,blankrows:true});staged=parseSheet(rows,importKind);const errors=staged.errors;let message=errors.length?`发现 ${errors.length} 处问题，请修改 Excel 后重新选择文件：\n`+errors.slice(0,8).join('\n')+(errors.length>8?'\n…':'' ):`可以导入 ${staged.records.length} 位学生${importKind==='roster'?`（新增 ${staged.records.filter(p=>!state.students.some(x=>x.id===p.id)).length} 人，其余更新）`:''}。`;message+=(staged.warnings.length?'\n'+staged.warnings.join('\n'):'');$('#importNotice').innerHTML=`<div class="notice ${errors.length?'error':''}">${esc(message)}</div>`;$('#importPreview').innerHTML='<table>'+rows.slice(0,7).map((r,i)=>'<tr>'+r.map(v=>i===0?`<th>${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')+'</tr>').join('')+'</table>';$('#commitImport').disabled=errors.length>0||!staged.records.length;}catch(e){$('#commitImport').disabled=true;staged=null;$('#importNotice').innerHTML='<div class="notice error">无法解析此工作表，请检查表头与内容。</div>';}}
function commitImport(){if(!staged||staged.errors.length)return;const examName=$('#examName')?.value.trim(),examDate=$('#examDate')?.value||'';if(importKind==='exam'&&!examName){toast('请填写考试名称');$('#examName').focus();return;}if(importKind==='exam'&&!toISODate(examDate)){toast('请选择考试时间');$('#examDate').focus();return;}checkpoint();if(importKind==='roster'){const map=new Map(state.students.map(p=>[p.id,p]));for(const p of staged.records)map.set(p.id,p);state.students=[...map.values()];}else{const id=uid(),scores=Object.fromEntries(staged.records.map(p=>[p.id,p.values])),ranks=Object.fromEntries(staged.records.map(p=>[p.id,p.ranks||{}]));state.exams.unshift({id,name:examName,date:toISODate(examDate),subjects:staged.subjects,scores,ranks,sourceFormat:staged.schoolFormat?'学校网站成绩汇总表':'班序模板'});state.exams=sortedExams();state.examId=id;examPreviewId=id;state.subject=staged.subjects.includes('总分')?'总分':staged.subjects[0];state.showScores=true;}$('#modal').close();changed(`已导入 ${staged.records.length} 位学生${importKind==='exam'?'的成绩':''}`);}
function editStudent(id){const p=state.students.find(s=>s.id===id);openModal(p?'编辑学生':'添加学生',`<div class="form-row"><div class="field"><label>学号（唯一）</label><input id="editId" maxlength="100" value="${esc(p?.id||'')}" ${p?'disabled':''}></div><div class="field"><label>姓名</label><input id="editName" maxlength="100" value="${esc(p?.name||'')}"></div></div><div class="form-row"><div class="field"><label>性别（选填）</label><input id="editGender" maxlength="20" value="${esc(p?.gender||'')}"></div><div class="field"><label>备注（选填）</label><input id="editNote" maxlength="200" value="${esc(p?.note||'')}"></div></div>`,`<button data-close>取消</button><button class="primary" id="saveStudent">保存</button>`);$('#saveStudent').onclick=()=>{const newId=$('#editId').value.trim(),name=$('#editName').value.trim();if(!newId||!name){toast('请填写学号和姓名');return;}if(!p&&state.students.some(s=>s.id===newId)){toast('该学号已存在');return;}checkpoint();const data={id:newId,name,gender:$('#editGender').value.trim(),note:$('#editNote').value.trim()};if(p)Object.assign(p,data);else state.students.push(data);$('#modal').close();changed('学生信息已保存');};}
function arrange(mode){if(!state.students.length){toast('请先导入学生名单');return;}if(mode==='clear'){confirmAction('清空座位安排','所有学生将移回待安排区，名单和考试成绩保留。可通过撤销恢复。',()=>{checkpoint();state.seats={};selected=null;changed('已清空座位');});return;}const empty=fillOrderFor(state.rows,state.extraRow).filter(k=>!state.seats[k]),waiting=state.students.filter(p=>!studentSeat(p.id));if(!empty.length||!waiting.length){toast('没有空座或没有待安排学生');return;}if(mode==='random'){for(let i=waiting.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[waiting[i],waiting[j]]=[waiting[j],waiting[i]];}}checkpoint();empty.forEach((k,i)=>{if(waiting[i])state.seats[k]=waiting[i].id;});changed(`已安排 ${Math.min(empty.length,waiting.length)} 位学生${waiting.length>empty.length?'，其余学生仍在待安排区':''}`);}
