$$('nav button').forEach(b=>b.onclick=()=>setPage(b.dataset.page));$('#templateBtn').onclick=templates;$('#importBtn').onclick=()=>openImport(page==='exams'?'exam':'roster');$('#importExamBtn').onclick=()=>openImport('exam');$('#className').onchange=e=>{checkpoint();state.className=e.target.value.trim()||'我的班级';changed();};$('#showScores').onchange=e=>{state.showScores=e.target.checked;changed();};$('#examSelect').onchange=e=>{state.examId=e.target.value;changed();};$('#subjectSelect').onchange=e=>{state.subject=e.target.value;changed();};$('#extraRow').onchange=e=>{checkpoint();state.extraRow=Number(e.target.value);changed('中央加座位置已更新，学生随座位移动');};
