$('#helpBtn').onclick=()=>openModal('使用指南','<p><b>1. 导入名单</b><br>下载 Excel 模板，在“学生名单”表填写学号与姓名。每位学生使用唯一学号；重复导入按学号更新，不会删除未包含的学生。</p><p><b>2. 导入成绩</b><br>在“考试成绩”表填写成绩，切换到考试成绩页面导入，并填写考试名称。科目列可自由增减。空白或“缺考”视为无成绩，0 分会正常保留。有总分列时直接使用；没有时自动求和，任一科目缺失则总分留空。</p><p><b>3. 安排座位</b><br>4 组、每组 2 列 6 排，共 48 个常规座位，加上中央 2 座。中央加座可选择所在的两排。拖动学生到座位自动吸附；两个已入座学生互换，待安排学生拖入有人的座位则原学生回待安排区。也可先点击学生再点击座位，适用于键盘或触屏操作。</p><p><b>4. 保存与备份</b><br>数据自动保存在当前设备的当前浏览器中，不会上传。清理浏览器或换设备可能丢失数据；请定期“导出备份”，需要时“恢复备份”。撤销最多保留本次打开后的 30 步数据操作。</p><p><b>5. 打印与导出</b><br>打印会保留当前成绩显示状态。浏览器打印窗口可另存为 PDF。“排座操作”中可导出座位 Excel。示例数据仅用于体验，可撤销恢复空白。</p>');

// Group numbers run right to left; the two central seats do not rotate.
function rotateGroups(){
 if(!Object.keys(state.seats).some(k=>k.startsWith('R'))){toast('常规座位还没有学生，请先安排座位');return;}
 checkpoint();const next={};for(const [seat,id] of Object.entries(state.seats)){
  if(seat.startsWith('X'))next[seat]=id;
  else{const row=Number(seat[1]),col=Number(seat[3]);next[`R${row}C${col<=2?col+6:col-2}`]=id;}
 }
 state.seats=next;selected=null;changed('大组已轮换：1 → 2 → 3 → 4 → 1；中央加座保持原位');
}
const callLabels={all:'全班学生',excellent:'优秀',middle:'中等',support:'后进生',ungraded:'暂无成绩'};
let callCategory='all',calledIds=new Set(),callLog=[],callResult=null,callSignature='';
const rangeLabels={single:'单次考试',recent3:'最近 3 次平均',recent5:'最近 5 次平均',all:'全部考试平均'};
const subjectOrder=['语文','数学','英语','物理','化学','生物','政治','历史','地理','技术','总分'];
function callSubjectOptions(){const single=state.callRange==='single',lists=single?[examSubjects(getExam())]:state.exams.map(e=>examSubjects(e)),set=new Set();lists.forEach(a=>a.forEach(x=>set.add(x)));return [...set].sort((a,b)=>{const ia=subjectOrder.indexOf(a),ib=subjectOrder.indexOf(b);return (ia<0?99:ia)-(ib<0?99:ib)||a.localeCompare(b,'zh-CN');});}
function callSubjectName(){const opts=callSubjectOptions();if(state.callSubject&&opts.includes(state.callSubject))return state.callSubject;if(opts.includes(state.subject))return state.subject;return opts[0]||'总分';}
function callExamPool(){const subject=callSubjectName();if(state.callRange==='single'){const ex=getExam();return ex&&examSubjects(ex).includes(subject)?[ex]:[];}const n=state.callRange==='recent3'?3:state.callRange==='recent5'?5:Infinity;return sortedExams().filter(e=>examSubjects(e).includes(subject)).slice(0,n);}
function callScore(id){const pool=callExamPool(),subject=callSubjectName(),vals=pool.map(e=>e.scores?.[id]?.[subject]).filter(v=>typeof v==='number'&&Number.isFinite(v));if(!vals.length)return {score:null,count:0,total:pool.length};return {score:Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*100)/100,count:vals.length,total:pool.length};}
function rankedGroups(){
 const ranked=[],ungraded=[];
 for(const p of state.students){const r=callScore(p.id);if(r.score!==null)ranked.push({student:p,score:r.score,count:r.count,total:r.total});else ungraded.push({student:p,score:null,count:0,total:r.total,rank:null,category:'ungraded'});}
 ranked.sort((a,b)=>b.score-a.score||a.student.id.localeCompare(b.student.id,'zh-CN',{numeric:true}));
 const groups={all:[],excellent:[],middle:[],support:[],ungraded};
 for(let i=0;i<ranked.length;){let j=i+1;while(j<ranked.length&&ranked[j].score===ranked[i].score)j++;const avg=(i+1+j)/2,percent=(avg-.5)/ranked.length;const category=percent<=.3?'excellent':percent>=.7?'support':'middle';for(let k=i;k<j;k++){Object.assign(ranked[k],{rank:i+1,averageRank:avg,category});groups[category].push(ranked[k]);}i=j;}
 groups.all=[...ranked,...ungraded];return groups;
}
function syncCallRound(){const signature=JSON.stringify([state.examId,state.callRange,state.callSubject,callSubjectName(),state.students,state.exams.map(e=>[e.id,e.date,e.subjects,e.scores])]);if(signature!==callSignature){callSignature=signature;calledIds.clear();callLog=[];callResult=null;}}
function renderCall(){
 syncCallRound();const single=state.callRange==='single',ex=getExam();
 $('#callExam').innerHTML=state.exams.length?sortedExams().map(e=>`<option value="${esc(e.id)}">${esc(e.name)}${toISODate(e.date)?`（${esc(toISODate(e.date))}）`:''}</option>`).join(''):'<option value="">暂无考试</option>';$('#callExam').value=state.examId;$('#callExam').disabled=!state.exams.length;
 $('#callExamWrap').classList.toggle('hidden',!single);
 $('#callRange').value=state.callRange;$('#callRange').disabled=!state.exams.length;
 const subject=callSubjectName(),opts=callSubjectOptions();
 $('#callSubject').innerHTML=opts.length?opts.map(x=>`<option>${esc(x)}</option>`).join(''):'<option>暂无已考科目</option>';$('#callSubject').value=subject;$('#callSubject').disabled=!opts.length;
 const poolExams=callExamPool(),groups=rankedGroups(),pool=groups[callCategory],noRepeat=$('#noRepeat').checked,available=pool.filter(p=>!noRepeat||!calledIds.has(p.student.id));
 const basis=single?`${ex?ex.name:'暂无考试'} · ${subject}`:`${rangeLabels[state.callRange]} · ${subject} · 实际取 ${poolExams.length} 场${poolExams.length?`（${esc(poolExams[poolExams.length-1].date?toISODate(poolExams[poolExams.length-1].date):'—')} → ${esc(toISODate(poolExams[0].date)||'—')}）`:''}`;
 $('#callCategories').innerHTML=Object.entries(callLabels).map(([key,label])=>`<button class="call-category ${callCategory===key?'active':''}" data-category="${key}" aria-pressed="${callCategory===key}">${label}<b>${groups[key].length} <small>人</small></b><small>${{all:'全部名单（含暂无成绩）',excellent:'成绩前 30%',middle:'成绩中间 40%',support:'成绩后 30%',ungraded:'缺考／未录入'}[key]}</small></button>`).join('');
 $('#callPoolLabel').textContent=`当前范围：${callLabels[callCategory]} · ${single?'单次考试':rangeLabels[state.callRange]}${subject?' · '+subject:''}`;
 $('#callName').textContent=callResult?callResult.student.name:'准备好了吗？';
 $('#callDetail').textContent=callResult?`学号 ${callResult.student.id} · ${studentSeat(callResult.student.id)?seatLabel(studentSeat(callResult.student.id)):'待安排座位'} · ${basis}`:basis;
 $('#drawStudent').disabled=!available.length;$('#drawStudent').textContent=pool.length&&!available.length?'本类已全部点过':'随机点名';$('#callRemaining').textContent=`当前范围 ${pool.length} 人 · ${noRepeat?'本轮还可抽取':'可抽取'} ${available.length} 人`;
 $('#callHistory').textContent=callLog.length?'本轮已点名 '+callLog.length+' 次（最近 12 次）：'+callLog.slice(-12).reverse().map(x=>`${x.name}（${x.id}）`).join('、'):'本轮还没有点名记录。';
 const scoreHead=single?subject:`${subject}（均分）`;
 $('#callMembers').innerHTML=pool.length?`<table><thead><tr><th>名次</th><th>学号</th><th>姓名</th><th>${esc(scoreHead)}</th><th>参与场次</th><th>分类</th><th>本轮状态</th></tr></thead><tbody>${pool.map(x=>`<tr><td>${x.rank??'—'}</td><td>${esc(x.student.id)}</td><td>${esc(x.student.name)}</td><td>${x.score??'—'}</td><td>${x.total?`${x.count} / ${x.total}`:'—'}</td><td>${callLabels[x.category]}</td><td>${calledIds.has(x.student.id)?'已点名':'未点名'}</td></tr>`).join('')}</tbody></table>`:'<div class="table-empty">此分类暂无学生，请选择其他分类或导入成绩。</div>';
}
function drawStudent(){syncCallRound();const pool=rankedGroups()[callCategory].filter(p=>!$('#noRepeat').checked||!calledIds.has(p.student.id));if(!pool.length){renderCall();toast('此范围暂无可点名学生，可切换分类或开始新一轮');return null;}const choice=pool[Math.floor(Math.random()*pool.length)];calledIds.add(choice.student.id);callLog.push({id:choice.student.id,name:choice.student.name});callResult=choice;renderCall();const label=$('#callName');label.classList.remove('flash');void label.offsetWidth;label.classList.add('flash');return choice.student.id;}
$('#rotateBtn').onclick=rotateGroups;
$('#callExam').onchange=e=>{state.examId=e.target.value;changed();};
$('#callRange').onchange=e=>{state.callRange=e.target.value;state.callSubject='';changed();};$('#callSubject').onchange=e=>{state.callSubject=e.target.value;changed();};
$('#callCategories').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;callCategory=b.dataset.category;callResult=null;renderCall();};
$('#noRepeat').onchange=()=>{callResult=null;renderCall();};
$('#drawStudent').onclick=drawStudent;
$('#resetRound').onclick=()=>{calledIds.clear();callLog=[];callResult=null;renderCall();toast('已开始新一轮点名');};

renderDiscTypes();render();setPage('seat');
